import re

from robot.api import logger

from ta_egate_cmd_parser.egate_output_parser_base import EgateDispCommandsOutputParser
from ta_egate_cmd_parser.egate_command_base import EgateCommandBase
from ta_egate_cmd_parser.utils.converters import create_dict_with_key


class RfhPortDispFailure(Exception):
    """
    Exception class for rfh_port_disp
    """
    pass


class RfhPortDisp(EgateCommandBase):
    """
    Parser for rfh_port_disp command output.
    """

    def __init__(self, **params):
        """

        :param params:
        """
        super(RfhPortDisp, self).__init__()
        self.command = 'rfh_port_disp'
        self.params = params
        self.executed_phrase = r'.*?EGATE>'
        self.fail_regexp = 'Error'
        self.to_execute = self.command
        self._build_command()
        logger.debug('{}: {} command to execute:\n{}'.format(self.__class__.__name__, self.command, self.to_execute))

    def execute(self, egate_id=0):
        """
        Execute rfh_port_disp command.
        :return: command status and output
        """
        status, output = super(RfhPortDisp, self).execute(egate_id=egate_id, command=self.to_execute, fail_regexp=self.fail_regexp)
        if status:
            return status, output
        else:
            raise RfhPortDispFailure(output)

    def execute_and_parse(self, egate_id=0):
        """
        Execute egate cmd and parse its output.

        :return: Parsed cmd output
        """
        status, output = super(RfhPortDisp, self).execute(egate_id=egate_id, command=self.to_execute, fail_regexp=self.fail_regexp)
        if status:
            parsed_output = self._parse_with_enb_id(output)
            logger.debug('{}: {} cmd parsed output:\n{}'.format(self.__class__.__name__, self.command, parsed_output))
            return parsed_output
        else:
            raise RfhPortDispFailure(output)

    def _build_command(self):
        """
        Build rfh_port_disp command.
        :return: None
        """
        for param, value in list(self.params.items()):
            self.to_execute += ' {}={}'.format(param, value)

    def _parse_with_enb_id(self, cmd_output):
        """

        :param cmd_output:
        :return:

        Input:
        Axc Configuration Display
        ============================================
        RE  branch  direction  eNB  cell  antIndex
        --------------------------------------------
        0   0       DL/UL      1    11    0
        0   1       DL/UL      1    11    1
        0   2       DL/UL      1    12    0
        0   3       DL/UL      1    12    1
        ============================================

        Port Configuration Display
        ======================================================
        RE  Port Id  Link Type  Physical Link Id  Speed
        ------------------------------------------------------
        0   1        Physical   1                 4915,2Mbps
        0   2        None       0                 None
        ======================================================

        Axc Configuration Display
        ============================================
        RE  branch  direction  eNB  cell  antIndex
        --------------------------------------------
        1   0       DL         1    13    0
        1   1       DL         1    13    1
        ============================================

        Port Configuration Display
        ======================================================
        RE  Port Id  Link Type  Physical Link Id  Speed
        ------------------------------------------------------
        1   1        Physical   2                 4915,2Mbps
        1   2        None       0                 None
        ======================================================

        Supported Subbands: 1-2-3-4


        Output:
        {
            '0': {
                '0': {
                    'RE': '0',
                    'antIndex': '0',
                    'branch': '0',
                    'cell': '11',
                    'direction': 'DL/UL',
                    'eNB': '1'
                },
                '1': {
                    'RE': '0',
                    'antIndex': '1',
                    'branch': '1',
                    'cell': '11',
                    'direction': 'DL/UL',
                    'eNB': '1'
                },
                'Supported subbands': ''
            },
            '1': {
                '0': {
                    'RE': '1',
                    'antIndex': '0',
                    'branch': '0',
                    'cell': '12',
                    'direction': 'DL',
                    'eNB': '1'
                },
                '1': {
                    'RE': '1',
                    'antIndex': '1',
                    'branch': '1',
                    'cell': '12',
                    'direction': 'DL',
                    'eNB': '1'
                },
                'Supported subbands': '1-2-3-4'
            }
        }

        Where main keys are rfh_id

        """
        cmd_output = re.sub(r'\r', '', cmd_output)
        rrh_list = re.findall(r'(={3,}\n+RE.*branch[\s\S]*?\={3,}\n)', cmd_output)
        enb_rrh_info = dict()

        if rrh_list:
            for rrh in rrh_list:
                cmd_parser = EgateDispCommandsOutputParser(rrh)
                output = cmd_parser.get_list_of_output_parsed_lines()

                rrh_info = create_dict_with_key(key="branch", list_of_output_parsed_lines=output)
                rfh_id = rrh_info[list(rrh_info.keys())[0]]['RE']

                enb_rrh_info[rfh_id] = rrh_info
        return enb_rrh_info
